-- 먼저 사용자 ID 조회
WITH user_to_delete AS (
  SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com'
)
-- 메시지 삭제 (발신자 또는 수신자)
DELETE FROM messages 
WHERE sender_id IN (SELECT id FROM user_to_delete) 
   OR recipient_id IN (SELECT id FROM user_to_delete);

-- 멘토 프로필 삭제
DELETE FROM "mentorProfiles" 
WHERE user_id IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 버그 리포트 삭제
DELETE FROM "bugReports" 
WHERE user_id IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 사용자 계정 삭제
DELETE FROM users WHERE email = 'syoung.choi327@gmail.com';
